CREATE TABLE IF NOT EXISTS hr_mitarbeiter_gratis_50 (mitarbeiter_id VARCHAR(20) PRIMARY KEY, vorname VARCHAR(50), nachname VARCHAR(50), strasse_hausnummer VARCHAR(100), plz VARCHAR(10), ort VARCHAR(50), sv_nummer VARCHAR(30), geschlecht VARCHAR(20), abteilung VARCHAR(50), position VARCHAR(100), arbeitszeit_modell VARCHAR(30), wochenstunden DECIMAL(5,2), ueberstunden_gesamt DECIMAL(5,2), ueberstunden_genommen DECIMAL(5,2), ueberstunden_verbleibend DECIMAL(5,2), ausgezahlte_ueberstunden_netto DECIMAL(10,2), gehalt_brutto DECIMAL(10,2), steuerklasse INT, lohnsteuer DECIMAL(10,2), rentenversicherung_an DECIMAL(10,2), arbeitslosenversicherung_an DECIMAL(10,2), krankenversicherung_an DECIMAL(10,2), pflegeversicherung_an DECIMAL(10,2), gehalt_netto DECIMAL(10,2), krankenkasse VARCHAR(100), iban_mitarbeiter VARCHAR(35), bundesbank_textschluessel VARCHAR(10), urlaubstage_gesamt INT, urlaubstage_genommen INT, urlaubstage_verbleibend INT, eintritt_datum VARCHAR(15), austritt_datum VARCHAR(15), status VARCHAR(30));

